var st = global.get('corolla_status') || {
    state: "VEHICLE_OFF",
    engine: false,
    ignition: false,
    red: false,
    blue: false,
    highBeam: false,
    headlights: false,
    door1: true,
    door2: true,
    starts: 0,
    vibrationAlert: false,
    vibrationCount: 0,
    starterBlocked: false,
    temperature: 28,
    light: 45,
    appEnabled: true
};

var cmd = null;
var notifyText = "";
var emailSubject = "";
var emailBody = "";
var themeColor = "#38bdf8";

// 0. التحقق من أمر زر تفعيل/إيقاف صلاحية التطبيق من التليجرام
if (typeof msg.payload === 'string') {
    var rawInput = msg.payload.trim();
    if (rawInput === 'cmd_toggle_app') {
        st.appEnabled = !st.appEnabled;
        themeColor = st.appEnabled ? "#22c55e" : "#ef4444";
        notifyText = st.appEnabled
            ? "✅ *[ صلاحية التطبيق ]*\n\n• تم *تفعيل* التحكم بالسيارة عبر التطبيق بنجاح."
            : "❌ *[ صلاحية التطبيق ]*\n\n• تم *إيقاف* صلاحية التحكم عبر التطبيق وحظر الأوامر!";

        global.set('corolla_status', st);
    }
}

// 🛑 [الشرط الأمني الصارم]: إذا كانت صلاحية التطبيق موقوفة، وجاء أي أمر من التطبيق (وليس من تليجرام)، يتم حظره فوراً
var isFromTelegram = (typeof msg.payload === 'string' && msg.payload.trim() === 'cmd_toggle_app') || msg.chatId;

if (!st.appEnabled && !isFromTelegram) {
    themeColor = "#ef4444";
    notifyText = "⚠️ *[ محاولة وصول مرفوضة ]*\n\n❌ عذراً، صلاحية التحكم عبر التطبيق *موقفة حالياً* من قبل مالك السيارة عبر التليجرام.";
    global.set('corolla_status', st);

    var tgChatId = msg.chatId || (msg.payload && msg.payload.chatId) || "YOUR_TELEGRAM_CHAT_ID";
    var blockedTg = {
        payload: {
            chatId: tgChatId,
            type: "message",
            content: notifyText,
            options: {
                parse_mode: "Markdown",
                reply_markup: {
                    inline_keyboard: [
                        [{ text: st.appEnabled ? "🟢 التطبيق: (مفعل - اضغط للإيقاف)" : "🔴 التطبيق: (موقوف - اضغط للتفعيل)", callback_data: "cmd_toggle_app" }],
                        [{ text: "🚗 تشغيل المحرك", callback_data: "cmd_i" }, { text: "⚡ سويتش الإشعال", callback_data: "cmd_s" }],
                        [{ text: "🛑 إطفاء المحرك", callback_data: "cmd_o" }, { text: "📊 تقرير الحالة", callback_data: "cmd_status" }],
                        [{ text: "💡 كشافات رئيسية", callback_data: "cmd_l" }, { text: "🔦 الضوء العالي", callback_data: "cmd_h" }],
                        [{ text: "🔴 إضاءة حمراء", callback_data: "cmd_r" }, { text: "🔵 إضاءة زرقاء", callback_data: "cmd_b" }],
                        [{ text: "🔓 قفل/فتح الأبواب", callback_data: "cmd_d" }, { text: "🔓 فتح الشنطة", callback_data: "cmd_t" }]
                    ]
                }
            }
        }
    };
    return [null, null, null, blockedTg, null, null];
}

// 1. استخراج الأوامر بمرونة تامة سواء من الكتابة أو من أزرار التليجرام
if (typeof msg.payload === 'string' && msg.payload.trim() !== 'cmd_toggle_app') {
    var raw = msg.payload.trim();
    if (raw !== 'PULSE' && raw.length > 0) {
        var upperRaw = raw.toUpperCase();
        var lowerRaw = raw.toLowerCase();

        if (upperRaw === "START" || upperRaw === "سلف" || upperRaw === "تشغيل" || lowerRaw === "cmd_s") {
            cmd = "S";
        } else if (upperRaw === "IGNITION" || upperRaw === "سويتش" || upperRaw === "تهيئة" || lowerRaw === "cmd_i") {
            cmd = "I";
        } else if (upperRaw === "OFF" || upperRaw === "إطفاء" || upperRaw === "اطفاء" || upperRaw === "16" || lowerRaw === "cmd_o") {
            cmd = "O";
        } else if (upperRaw === "DOOR" || upperRaw === "LOCK" || upperRaw === "قفل" || lowerRaw === "cmd_d") {
            cmd = "D";
        } else if (upperRaw === "TRUNK" || upperRaw === "شنطة" || lowerRaw === "cmd_t") {
            cmd = "T";
        } else if (upperRaw === "HEADLIGHTS" || upperRaw === "نور" || upperRaw === "كشافات" || lowerRaw === "cmd_l") {
            cmd = "L";
        } else if (upperRaw === "HIGHBEAM" || upperRaw === "عالي" || lowerRaw === "cmd_h") {
            cmd = "H";
        } else if (upperRaw === "RED" || upperRaw === "احمر" || upperRaw === "أحمر" || lowerRaw === "cmd_r") {
            cmd = "R";
        } else if (upperRaw === "BLUE" || upperRaw === "ازرق" || upperRaw === "أزرق" || lowerRaw === "cmd_b") {
            cmd = "B";
        } else if (upperRaw === "STATUS" || upperRaw === "حالة" || upperRaw === "تقرير" || lowerRaw === "cmd_status") {
            cmd = "STATUS";
        } else if (raw === 's') {
            cmd = 's';
        } else {
            cmd = raw.length === 1 ? raw.toUpperCase() : raw;
        }
    }
} else if (typeof msg.payload === 'number') {
    if (msg.payload === 16) {
        cmd = "O";
    }
} else if (typeof msg.payload === 'boolean') {
    var top = (msg.topic || "").toUpperCase();
    if (top.includes("START")) cmd = "S";
    else if (top.includes("OFF")) cmd = "O";
    else if (top.includes("RED")) cmd = "R";
    else if (top.includes("BLUE")) cmd = "B";
    else if (top.includes("LIGHT") || top.includes("HEADLIGHT")) cmd = "L";
    else if (top.includes("HIGHBEAM")) cmd = "H";
    else if (top.includes("IGNITION")) cmd = "I";
    else if (top.includes("DOOR")) cmd = "D";
} else if (msg.payload && typeof msg.payload === 'object') {
    if (msg.payload.vibrationAlert === true || msg.event === "vibration" || msg.topic === "vibration") {
        st.vibrationCount = (st.vibrationCount || 0) + 1;
        st.vibrationAlert = true;
        themeColor = "#eab308";
        notifyText = "🚨 *[تنبيه أمني عاجل]* 🚨\n\n" +
                     "⚠️ تم رصد *اهتزاز أو حركة مريبة* بجسم السيارة!\n" +
                     "🔍 يرجى تفقد أمان المركبة فوراً.";

        emailSubject = "🚨 [تحذير أمني] رصد اهتزاز في سيارة Corolla";
        emailBody = "⚠️ تحذير أمني: تم رصد اهتزاز أو محاولة تلاعب بالسيارة الآن!\n" +
            "• عدد مرات رصد الاهتزاز: " + st.vibrationCount + "\n" +
            "• حالة المنظومة: " + st.state + "\n" +
            "• وقت الرصد: " + new Date().toLocaleString('ar-YE');
    } else if (msg.payload.state) {
        st = Object.assign(st, msg.payload);
        st.engine = (st.state === "ENGINE_RUNNING");
        st.ignition = (st.state === "ENGINE_RUNNING" || st.state === "COILS_ON" || st.state === "IGNITION_ON");
        global.set('corolla_status', st);
        return [{ payload: st }, null, null, null, null, null];
    } else if (msg.payload.cmd || msg.payload.command || msg.payload.action) {
        var rawCmd = String(msg.payload.cmd || msg.payload.command || msg.payload.action).trim();
        cmd = (rawCmd.length === 1 && rawCmd !== 's') ? rawCmd.toUpperCase() : rawCmd;
    }
}

// متغير لتحديد ما إذا كان الطلب قادماً من تليجرام كأمر عرض قائمة (مثل /start)
var isMenuRequest = false;
var normInput = (typeof msg.payload === 'string') ? msg.payload.trim().toLowerCase() : "";
if (normInput === '/start' || normInput === '/menu' || normInput === 'قائمة' || normInput === 'اوامر' || normInput === 'أوامر') {
    isMenuRequest = true;
    notifyText = "🚗 *لوحة التحكم الذكي بسيارة Toyota Corolla:*\nاختر الأمر المناسب من الأزرار التالية:";
    themeColor = "#38bdf8";
}

// 2. معالجة وتحديث الحالات والردود الدقيقة
if (cmd) {
    st.vibrationAlert = false;

    if (cmd === 'I') {
        themeColor = "#22c55e";
        if (st.state === "VEHICLE_OFF") {
            st.state = "COILS_ON";
            st.ignition = true;
            notifyText = "⚡ *[ إدارة السويتش — الضغطة الأولى ]*\n\n" +
                         "•  *الحالة:* `تم تشغيل الطبلون والبخاخات (المنفذ 22 و 23)`\n" +
                         "•  الطبلون مستعد ودورة الإشعال جاهزة.";
        } else if (st.state === "COILS_ON" || st.state === "ENGINE_RUNNING") {
            st.state = "IGNITION_ON";
            st.engine = false;
            notifyText = "🔋 *[ وضع السويتش — الضغطة الثانية ]*\n\n" +
                         "• 🛑 تم إطفاء البخاخات وإبقاء طاقة الطبلون فقط.\n" +
                         "•  الكهرباء مستمرة على السويتش.";
        } else {
            st.state = "VEHICLE_OFF";
            st.ignition = false;
            st.engine = false;
            notifyText = "🛑 *[ إيقاف كامل — الضغطة الثالثة ]*\n\n" +
                         "•  تم فصل طاقة الطبلون والمنظومة بالكامل.";
        }
    } else if (cmd === 'S') {
        if (st.state !== "COILS_ON") {
            themeColor = "#ef4444";
            notifyText = "⚠️ *[ تنبيه أمني للتشغيل ]*\n\n" +
                         "❌ *عذراً لا يمكن تشغيل المحرك!* \n" +
                         "• يرجى أولاً تشغيل الطبلون والبخاخات لتفعيل الطبلون بأمان.";
            cmd = null;
        } else {
            st.state = "ENGINE_RUNNING";
            st.engine = true;
            st.ignition = true;
            st.starts = (st.starts || 0) + 1;
            themeColor = "#22c55e";
            notifyText = "🚗 *[ إشعار تشغيل المحرك ]*\n\n" +
                         "•  *الحالة:* `تم تشغيل المحرك والسيارة بالكامل بنجاح`\n" +
                         "•  *إجمالي التشغيلات:* `" + st.starts + " مرة`\n" +
                         "•  *الوقت:* `" + new Date().toLocaleTimeString('ar-SA') + "`";

            emailSubject = "🚗 إشعار تشغيل محرك سيارة Corolla";
            emailBody = "تم تشغيل محرك السيارة بالكامل بنجاح عبر النظام الذكي.\n" +
                "• عدد مرات التشغيل الإجمالية: " + st.starts + "\n" +
                "• حالة المحرك: يعمل (RUNNING)\n" +
                "• وقت التشغيل: " + new Date().toLocaleString('ar-YE');
        }
    } else if (cmd === 'O') {
        st.state = "VEHICLE_OFF";
        st.engine = false;
        st.ignition = false;
        st.highBeam = false;
        st.headlights = false;
        st.red = false;
        st.blue = false;
        st.vibrationAlert = false;
        themeColor = "#ef4444";
        notifyText = "🛑 *[ إطفاء وتأمين شامل ]*\n\n" +
                     "•  *حالة السيارة:* `تم إطفاء وتأمين السيارة بالكامل`\n" +
                     "•  تم فصل كافة الدوائر الكهربائية والأضواء.";

        emailSubject = "🛑 إشعار إطفاء وتأمين سيارة Corolla";
        emailBody = "تم إطفاء وتأمين السيارة بالكامل وفصل الدوائر.\n" +
            "• حالة المركبة: مطفأة بالكامل (VEHICLE_OFF)\n" +
            "• وقت الإطفاء: " + new Date().toLocaleString('ar-YE');
    } else if (cmd === 'R') {
        st.red = !st.red;
        notifyText = "🔴 *[ وحدة الضوء الأحمر ]*\n\n" +
                     "• 💡 *الحالة:* " + (st.red ? "`تم تشغيل الضوء الأحمر`" : "`تم إطفاء الضوء الأحمر`");
    } else if (cmd === 'B') {
        st.blue = !st.blue;
        notifyText = "🔵 *[ وحدة الضوء الأزرق ]*\n\n" +
                     "• 💡 *الحالة:* " + (st.blue ? "`تم تشغيل الضوء الأزرق`" : "`تم إطفاء الضوء الأزرق`");
    } else if (cmd === 'H') {
        st.highBeam = !st.highBeam;
        notifyText = "🔦 *[ الضوء العالي ]*\n\n" +
                     "•  *الحالة:* " + (st.highBeam ? "`تم تشغيل الضوء العالي`" : "`تم إطفاء الضوء العالي`");
    } else if (cmd === 'L') {
        st.headlights = !st.headlights;
        notifyText = "💡 *[ الأنوار والكشافات ]*\n\n" +
                     "•  *الحالة:* " + (st.headlights ? "`تم تشغيل الكشافات الرئيسية`" : "`تم إطفاء الكشافات الرئيسية`");
    } else if (cmd === 'D') {
        st.door1 = !st.door1;
        notifyText = "🔓 *[ نظام الأبواب ]*\n\n" +
                     "• 🔒 *الحالة:* " + (st.door1 ? "`تم قفل الأبواب ومغلقة بأمان`" : "`تم فتح الأبواب بنجاح`");
    } else if (cmd === 'T') {
        st.door2 = false;
        notifyText = "🔓 *[ صندوق السيارة ]*\n\n" +
                     "•  *الشنطة:* `تم فتح الشنطة بنجاح`";
    } else if (cmd === 'STATUS') {
        var stStatus = global.get('corolla_status') || {};
        var stateStr = stStatus.state || "متوقفة / VEHICLE_OFF";
        var starts = stStatus.starts || 0;
        var temp = stStatus.temperature || 28;
        var vibCount = stStatus.vibrationCount || 0;
        var appStatText = stStatus.appEnabled ? "🟢 مسموح ومفعل" : "🔴 موقوف ومحظور";

        notifyText = "📊 *تقرير الحالة المباشر لسيارة Corolla:*\n\n" +
                     "• 🚗 *حالة المنظومة:* `" + stateStr + "`\n" +
                     "• 📱 *صلاحية التطبيق:* `" + appStatText + "`\n" +
                     "• 🌡 *حرارة الكابينة:* `" + temp + " °C`\n" +
                     "• 🔄 *مرات التشغيل:* `" + starts + " مرات`\n" +
                     "• 🚨 *سجل الاهتزازات:* `" + vibCount + " إنذارات`";
    }
}

global.set('corolla_status', st);

var outUI = { payload: st };
var outCmd = (cmd !== null && st.appEnabled) ? { payload: String(cmd), topic: "corolla/control/cmd" } : null;
var outMqttStatus = null;

// 1. رسالة التليجرام (تظهر مع الأزرار التفاعلية حصرياً لتليجرام)
var outTg = null;
if (notifyText !== "") {
    var tgChatId = msg.chatId || (msg.payload && msg.payload.chatId) || "YOUR_TELEGRAM_CHAT_ID";

    outTg = {
        payload: {
            chatId: tgChatId,
            type: "message",
            content: notifyText,
            options: {
                parse_mode: "Markdown",
                reply_markup: {
                    inline_keyboard: [
                        [{ text: st.appEnabled ? "🟢 التطبيق: (مفعل - اضغط للإيقاف)" : "🔴 التطبيق: (موقوف - اضغط للتفعيل)", callback_data: "cmd_toggle_app" }],
                        [{ text: "🚗 تشغيل المحرك", callback_data: "cmd_i" }, { text: "⚡ سويتش الإشعال", callback_data: "cmd_s" }],
                        [{ text: "🛑 إطفاء المحرك", callback_data: "cmd_o" }, { text: "📊 تقرير الحالة", callback_data: "cmd_status" }],
                        [{ text: "💡 كشافات رئيسية", callback_data: "cmd_l" }, { text: "🔦 الضوء العالي", callback_data: "cmd_h" }],
                        [{ text: "🔴 إضاءة حمراء", callback_data: "cmd_r" }, { text: "🔵 إضاءة زرقاء", callback_data: "cmd_b" }],
                        [{ text: "🔓 قفل/فتح الأبواب", callback_data: "cmd_d" }, { text: "🔓 فتح الشنطة", callback_data: "cmd_t" }]
                    ]
                }
            }
        }
    };
}

// 2. رسالة الواتساب
var outWa = null;
if (notifyText !== "" && !isMenuRequest) {
    outWa = {
        payload: {
            wa_custom_text: notifyText,
            message: notifyText,
            text: notifyText
        }
    };
}

var outMail = null;
if (emailSubject !== "" && emailBody !== "") {
    var formattedText = emailBody.replace(/\n/g, "<br>");
    var emailCardHtml = "<div dir='rtl' style='background-color:#0b1120;padding:20px;border-radius:10px;color:#fff;border:2px solid " + themeColor + ";'>" +
        "<h3 style='color:" + themeColor + ";'>" + emailSubject + "</h3>" +
        "<div>" + formattedText + "</div></div>";
    outMail = {
        topic: emailSubject,
        payload: emailCardHtml
    };
}

return [outUI, outCmd, outMqttStatus, outTg, outWa, outMail];

var body = msg.payload || {};
var query = msg.req ? (msg.req.query || {}) : {};
var rawCmd = body.cmd || body.command || query.cmd || query.command;

if (rawCmd) {
    var cmd = String(rawCmd).trim();

    // إرسال الأمر للسيارة
    var msgControl = { payload: cmd };

    msg.statusCode = 200;
    msg.payload = {
        status: "success",
        command_sent: cmd,
        timestamp: new Date().toISOString()
    };

    return [msgControl, msg];
} else {
    msg.statusCode = 400;
    msg.payload = {
        status: "error",
        message: "Missing cmd parameter"
    };
    return [null, msg];
}

var status = global.get('corolla_status') || {state: "VEHICLE_OFF", connected: true};
msg.payload = {
    status: "online",
    system: "Toyota Corolla Smart Control",
    vehicle_state: status,
    timestamp: new Date().toISOString()
};
return msg;

var body = msg.payload || {};
var query = msg.req ? (msg.req.query || {}) : {};

var text = body.wa_custom_text || body.message || body.text || query.message || query.text || "🚗 تنبيه من تطبيق التحكم الذكي بسيارة Corolla!";
var phone = body.phone || body.to || query.phone || query.to || flow.get('wa_phone') || "YOUR_WHATSAPP_PHONE_NUMBER";
var token = body.token || query.token || flow.get('wa_token') || "YOUR_WASENDER_BEARER_TOKEN";

phone = String(phone).replace('+', '').trim();

flow.set('wa_phone', phone);
flow.set('wa_token', token);

msg.phone = phone;
msg.token = token;
msg.payload = {
    wa_custom_text: text,
    phone: phone,
    token: token
};

var resPayload = {
    status: "success",
    delivered_to_gateway: true,
    recipient: phone,
    message: text,
    timestamp: new Date().toISOString()
};

return [msg, { payload: resPayload }];

var phone = msg.phone || flow.get('wa_phone') || "YOUR_WHATSAPP_PHONE_NUMBER";
phone = String(phone).replace('+', '').trim();

var bearerToken = msg.token || flow.get('wa_token') || "YOUR_WASENDER_BEARER_TOKEN";

var text = "";
if (msg.payload && msg.payload.wa_custom_text) {
    text = msg.payload.wa_custom_text;
} else if (msg.payload && msg.payload.message) {
    text = msg.payload.message;
} else if (typeof msg.payload === 'string') {
    text = msg.payload;
}

if (!text) return null;

msg.url = "https://wasenderapi.com/api/send-message";
msg.method = "POST";
msg.headers = {
    "Content-Type": "application/json",
    "Authorization": "Bearer " + bearerToken
};
msg.payload = {
    "to": phone,
    "phone": phone,
    "message": text,
    "text": text
};

return msg;

var st = global.get('corolla_status') || {};
var apiKey = "YOUR_THINGSPEAK_WRITE_API_KEY";

var f1 = st.engine ? 1 : 0;
var f2 = st.vibrationCount || 0;
var f3 = st.starts || 0;
var f4 = st.door1 ? 1 : 0;
var f5 = st.headlights ? 1 : 0;
var f6 = st.highBeam ? 1 : 0;
var f7 = st.vibrationCount || 0;
var f8 = (st.engine || st.ignition) ? 1 : 0;

// إرسال القيم كـ Object لتقوم عقدة HTTP بترجمتها تلقائياً
msg.payload = {
    api_key: apiKey,
    field1: f1,
    field2: f2,
    field3: f3,
    field4: f4,
    field5: f5,
    field6: f6,
    field7: f7,
    field8: f8
};

return msg;

// msg.payload عبارة عن JSON القادم من ESP32
var state = msg.payload.state;

// إذا كان المحرك شغال أو السويتش شغال، تعتبر الحالة ON (true)
if (state === "ENGINE_RUNNING" || state === "COILS_ON" || state === "IGNITION_ON") {
    msg.payload = true;
} else {
    msg.payload = false;
}

return msg;

format:
body, .nrdb-layout {
  background: radial-gradient(circle at 50% 10%, #080d18 0%, #020408 100%) !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
}

.nrdb-ui-group, .v-card {
  background: rgba(10, 16, 30, 0.82) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 18px !important;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.7) !important;
  padding: 16px !important;
}

.v-card-title, .nrdb-group-title {
  color: #94a3b8 !important;
  font-size: 11px !important;
  font-weight: 800 !important;
  letter-spacing: 1.5px !important;
  text-transform: uppercase !important;
}

.v-btn__overlay,
.v-btn__underlay {
  display: none !important;
  background: transparent !important;
}

.nrdb-ui-button button, .v-btn {
  background: linear-gradient(180deg, #182235 0%, #0d1524 100%) !important;
  border: 1.5px solid rgba(255, 255, 255, 0.16) !important;
